import {memo, Suspense, useCallback, useEffect, useMemo} from 'react'
import type {EntryPointProps} from 'react-relay'

import {useBranch, useSyncedBooleanQueryParam} from '../../../../hooks/routes'
import {getBuildType} from '../../../../selectors'
import {restApi} from '../../../../services/rest'
import type {BuildTypeId} from '../../../../types'
import {emptyArray} from '../../../../utils/empty'
import {subscribeOnBuildTypeEvents} from '../../../../utils/subscriber'
import {
  BUILD_CHANGES_LOADED,
  BUILD_INTERRUPTED,
  CHANGE_ADDED,
} from '../../../../utils/subscriptionEvents'
import {UserProperties} from '../../../../utils/userProperties'
import Loader from '../../../common/Loader/Loader'
import type {CommiterSelectQuery} from '../../../common/UserSelect/__generated__/CommiterSelectQuery.graphql'
import {
  ChangeContext,
  DEFAULT_CHANGES_LIST_CONTEXT,
} from '../../../packages/Changes/Change/Change.context'
import {useChangesFilter} from '../../../packages/Changes/Changes.hooks'
import ChangesFilter from '../../../packages/Changes/ChangesFilter/ChangesFilter'
import ChangesLog from '../../../packages/Changes/ChangesLog/ChangesLog'
import {useChangeLogLocator} from '../../../packages/Changes/ChangesLog/ChangesLog.hooks'
import {getChangeLogArg} from '../../../packages/Changes/ChangesLog/ChangesLog.utils'

import styles from './PendingChangesTab.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = {
  buildTypeId: BuildTypeId
}

type Queries = {
  commiterSelect: CommiterSelectQuery
}

type ExtraProps = {
  baseLocator: string
}

function PendingChangesTab({
  queries,
  props,
  extraProps,
}: EntryPointProps<Queries, {}, Props, ExtraProps>) {
  const {buildTypeId} = props
  const {baseLocator} = extraProps
  const branch = useBranch()
  const {isFilterChanged} = useChangesFilter(buildTypeId)

  const buildTypeInternalId = useAppSelector(state => getBuildType(state, buildTypeId)?.internalId)
  const [showFiles] = useSyncedBooleanQueryParam({
    param: 'showFiles',
    userProperty: UserProperties.SHOW_ALL_CHANGES_FILES,
  })

  const changesListContextValue = useMemo(
    () => ({...DEFAULT_CHANGES_LIST_CONTEXT, showFiles}),
    [showFiles],
  )
  const {withGraph} = changesListContextValue

  const locator = useChangeLogLocator({buildTypeId, branch, pending: true})

  const changeLogArg = useMemo(
    () =>
      locator != null
        ? getChangeLogArg({
            locator,
            changesOptions: {withFiles: showFiles, withUpdatePager: true},
            withGraph,
          })
        : null,
    [locator, withGraph, showFiles],
  )

  const [fetchChangeLog, {changes, changeLogReady}] = restApi.endpoints.getChangeLog.useLazyQuery({
    refetchOnFocus: true,
    selectFromResult: ({data}) => ({
      changes: data?.changes?.result ?? emptyArray,
      changeLogReady: data != null,
    }),
  })

  const fetch = useCallback(() => {
    if (changeLogArg != null) {
      fetchChangeLog(changeLogArg)
    }
  }, [changeLogArg, fetchChangeLog])

  useEffect(() => {
    if (buildTypeInternalId != null) {
      return subscribeOnBuildTypeEvents(
        buildTypeInternalId,
        [CHANGE_ADDED, BUILD_CHANGES_LOADED, BUILD_INTERRUPTED],
        fetch,
      )
    } else {
      fetch()
      return undefined
    }
  }, [buildTypeInternalId, fetch])

  return changeLogReady && locator != null ? (
    <div data-test-changes-advanced-view>
      {((changeLogReady && changes.length > 0) || isFilterChanged) && (
        <Suspense>
          <ChangesFilter
            className={styles.filter}
            buildTypeId={buildTypeId}
            baseLocator={baseLocator}
            commiterSelectQueryRef={queries.commiterSelect}
            withChangesFromDependenciesToggle
            withIncludeChangesInSettingsToggle={false}
          />
        </Suspense>
      )}
      <ChangeContext.Provider value={changesListContextValue}>
        <Suspense>
          <ChangesLog buildTypeId={buildTypeId} locator={locator} />
        </Suspense>
      </ChangeContext.Provider>
    </div>
  ) : (
    <Loader />
  )
}

export type PendingChangesTabComponent = typeof PendingChangesTab

export default memo(PendingChangesTab)
